define("mod_questionnaire/sendmessage",[],(function(){var apply=function(predicate){document.querySelectorAll("input.usercheckbox").forEach((function(box){box.checked=predicate(box)}))},bind=function(id,predicate){var trigger=document.getElementById(id);trigger&&trigger.addEventListener("click",(function(){apply(predicate)}))};return{init:function(){bind("checkall",(function(){return!0})),bind("checknone",(function(){return!1})),bind("checknotstarted",(function(box){return"0"===box.getAttribute("alt")})),bind("checkstarted",(function(box){return"1"===box.getAttribute("alt")}))}}}));
